// helper to create instance of component
function inst(id){
  const n = figma.getNodeById(id);
  if (n && (n.type === "COMPONENT")) return n.createInstance();
  return null;
}
function text(parent, str, x, y, w, size, weight, color, align){
  const t = figma.createText();
  t.characters = str;
  t.fontName = {family:"Inter", style:weight};
  t.fontSize = size;
  t.x = x; t.y = y;
  t.resize(w, size*1.3);
  t.fills = [{type:"SOLID", color}];
  if(align) t.textAlignHorizontal = align;
  parent.appendChild(t);
  return t;
}
function addFill(node, hex){
  const c = hexToRgb(hex);
  node.fills = [{type:"SOLID", color:c}];
}
function hexToRgb(hex){
  const h = hex.replace("#","");
  return {r:parseInt(h.substr(0,2),16)/255, g:parseInt(h.substr(2,2),16)/255, b:parseInt(h.substr(4,2),16)/255};
}

